{"content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Maps the CLI arguments to configuration keys. Mirrors the Replay parser shape: the subcommand is a
/// positional value, the paths are positional too, so this parser only normalises the
/// <c>AutoWrongCensus:*</c> keys.
/// </summary>
public static class CommandLineArgumentParser
{
	public static System.Collections.Generic.Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new System.Collections.Generic.Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		for (var i = 0; i < args.Length; i++)
		{
			var arg = args[i];
			if (arg.Equals("--trace", StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length)
			{
				dict["AutoWrongCensus:TracePath"] = args[++i];
			}
			else if (arg.StartsWith("--trace=", StringComparison.OrdinalIgnoreCase))
			{
				dict["AutoWrongCensus:TracePath"] = arg["--trace=".Length..];
			}
			else if (arg.Equals("--census-tsv", StringComparison.OrdinalIgnoreCase) && i + 1 < args.Length)
			{
				dict["AutoWrongCensus:CensusTsvPath"] = args[++i];
			}
			else if (arg.StartsWith("--census-tsv=", StringComparison.OrdinalIgnoreCase))
			{
				dict["AutoWrongCensus:CensusTsvPath"] = arg["--census-tsv=".Length..];
			}
		}

		return dict;
	}
}
