{"content":"namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>Relation and site vocabulary of the auto-wrong census (F-428 P12.13).</summary>
public static class AutoWrongRelations
{
	/// <summary>First relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>The line named a can/jar unit; the labelled row was the canned state, the accepted row was not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>The labelled head phrase was compound and the accepted parsed name kept only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>The head terms agreed but the FoodState masks differed.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>The head terms and state agreed; the accepted row landed on a different dataset tier.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>The head terms agreed and nothing above applied; the qualifier difference is recorded.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>The accepted row named a different food than the labelled row.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Catch-all for lines whose relation could not be decided (missing fields).</summary>
	public const string Other = "other";
}

/// <summary>
/// One classified auto-wrong line, in the census TSV's column order plus the diagnostics the summary needs.
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>Trace holdout id.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Ingredient line index.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set: <c>debug</c> or <c>batch</c>.</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Accepted-row vs key-row relation (see <see cref="AutoWrongRelations"/>).</summary>
	public string Relation { get; init; } = AutoWrongRelations.Other;

	/// <summary>Decision site: <c>reuse</c>, <c>override</c>, <c>curated</c> or <c>ranker</c>.</summary>
	public string Site { get; init; } = AutoWrongRelations.Other;

	/// <summary>Whether the normalised raw text is a key of <c>exact-overrides.json</c>.</summary>
	public string? OverrideKey { get; init; }

	/// <summary>Accepted row dataset tier; empty when the trace lacked it.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Labelled row dataset tier; empty when the trace lacked it.</summary>
	public string KeyTier { get get; init; } = string.Empty;

	/// <summary>Accepted row state mask.</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Labelled row state mask.</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The labelled row's head phrase (head term plus leading non-state words).</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>The accepted row's description.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>The labelled row's description.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw line text.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>Which dataType field was missing when the relation fell to <see cref="AutoWrongRelations.Other"/>.</summary>
	public string? MissingField { get; init; }

	/// <summary>Qualifier difference for <see cref="AutoWrongRelations.SameHeadOtherQualifier"/> lines.</summary>
	public IReadOnlyList<string> KeyOnlyQualifiers { get; init; } = [];

	/// <summary>Qualifier difference for <see cref="AutoWrongRelations.SameHeadOtherQualifier"/> lines.</summary>
	public IReadOnlyList<string> AcceptedOnlyQualifiers { get; init; } = [];

	/// <summary><c>true</c> when the accepted row's tier is higher than the labelled row's (row-choice-tier).</summary>
	public bool AcceptedHigherTier { get; init; }

	/// <summary><c>true</c> when the labelled row's tier is higher than the accepted row's (row-choice-tier).</summary>
	public bool KeyHigherTier { get; init; }
}
