{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Classification;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line: accepted row vs key row relation, plus the decision site.
/// Every token/state comparison goes through the production helpers (FdcNormalizer, FdcMatcher,
/// FdcDescriptionParser, IngredientLineResolver) — never a copy (F-428 D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private const string RelationNoLabel = "no-label";
	private const string RelationPackUnitState = "pack-unit-state";
	private const string RelationCompoundHeadLost = "compound-head-lost";
	private const string RelationStateMismatch = "state-mismatch";
	private const string RelationRowChoiceTier = "row-choice-tier";
	private const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";
	private const string RelationSiblingFood = "sibling-food";
	private const string RelationOther = "other";

	private const string SiteRanker = "ranker";
	private const string SiteOverride = "override";
	private const string SiteCurated = "curated";
	private const string SiteReuse = "reuse";

	private static readonly Regex PackUnitRegex = new(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase | RegexOptions.Compiled);

	private readonly FdcNormalizer _normalizer = new();
	private readonly string?[] _singleTokenScratch = new string[1];

	private readonly FdcLexicon _lexicon = FdcLexicon.Default;

	/// <summary>Builds the classifier over the production normalizer and the embedded override key set.</summary>
	/// <param name="normalizer">Production token normalizer.</param>
	/// <param name="overrideKeys">Production override key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	private readonly ExactOverrideKeyIndex _overrideKeys;

	private readonly FdcNormalizer _normalizerField = new();

	/// <summary>
	/// Classifies one line. Only <c>auto == true && correct == false</c> lines are classified; the
	/// caller filters.
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, site and compared rows.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var site = SiteFor(atom);
		var overrideKey = site == SiteOverride ? NormalizeOverrideKey(line.RawText) : string.Empty;

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyDesc = keyDesc,
			AcceptedDesc = acceptedDesc,
			RawText = line.RawText,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = RelationNoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		result.KeyHead = string.Join(' ', KeyHeadPhrase(keyTokens));
		result.KeyState = StateMask(keyTokens).ToString();
		result.AcceptedState = StateMask(acceptedTokens).ToString();

		var keyHead = FdcDescriptionParser.Parse(keyDesc, ToDataset(keyTier)).HeadTerm;
		var acceptedHead = acceptedDesc.Length > 0 ? FdcDescriptionParser.Parse(acceptedDesc, ToDataset(acceptedTier)).HeadTerm : string.Empty;
		var keyHeadTokens = SingularPhrase(keyHead);
		var acceptedHeadTokens = SingularPhrase(acceptedHead);
		var parsedNameTokens = SingularPhrase(atom?.ParsedName);

		if (PackUnitRegex.IsMatch(line.RawText)
			&& StateMask(keyTokens).HasFlag(FoodState.Canned)
			&& !StateMask(acceptedTokens).HasFlag(FoodState.Canned))
		{
			result.Relation = RelationPackUnitState;
			return result;
		}

		if (KeyHeadPhrase(keyTokens).Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(KeyHeadPhrase(keyTokens)[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = RelationCompoundHeadLost;
			return result;
		}

		var headsAgree = keyHeadTokens.SequenceEqual(acceptedHeadTokens, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			result.Relation = RelationSiblingFood;
			return result;
		}

		if (StateMask(keyTokens) != StateMask(acceptedTokens))
		{
			result.Relation = RelationStateMismatch;
			return result;
		}

		if (acceptedTier.Length > 0 && keyTier.Length > 0 && acceptedTier != keyTier)
		{
			result.Relation = RelationRowChoiceTier;
			return result;
		}

		if (acceptedTier.Length == 0 || keyTier.Length == 0)
		{
			result.Relation = RelationOther;
			result.MissingField = acceptedTier.Length == 0 ? "actualDataTypes" : "expectedDataTypes";
			return result;
		}

		result.Relation = RelationSameHeadOtherQualifier;
		var keyQualifiers = FdcDescriptionParser.Parse(keyDesc, ToDataset(keyTier)).Qualifiers;
		var acceptedQualifiers = FdcDescriptionParser.Parse(acceptedDesc, ToDataset(acceptedTier)).Qualifiers;
		result.KeyOnlyQualifiers = QualifierDiff(keyQualifiers, acceptedQualifiers);
		result.AcceptedOnlyQualifiers = QualifierDiff(acceptedQualifiers, keyQualifiers);
		return result;
	}

	/// <summary>Classifies the decision site of the first accepted atom.</summary>
	/// <param name="atom">The accepted atom (first accepted, else first).</param>
	/// <returns>The site; empty when the atom path is unknown.</returns>
	public string SiteFor(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => string.Empty,
		};
	}

	/// <summary>
	/// The key head phrase: normalized tokens up to the first token that production treats as a state
	/// or modifier word. Two or more words means the key names a compound food (e.g. "bread crumbs").
	/// </summary>
	/// <param name="tokens">Normalized key tokens.</param>
	/// <returns>The leading head tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	private bool CarriesStateToken(string token)
	{
		_singleTokenScratch[0] = token;
		return _lexicon.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	/// <summary>Combines the production state mask with the production satisfier mask.</summary>
	/// <param name="tokens">Normalized tokens.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState StateMask(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private static IReadOnlyList<string> QualifierDiff(IReadOnlyList<string> keyQualifiers, IReadOnlyList<string> acceptedQualifiers)
	{
		var key = keyQualifiers.Select(t => IngredientLineResolver.SingularizeToken(t)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToList();
		var accepted = acceptedQualifiers.Select(t => IngredientLineResolver.SingularizeToken(t)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToList();
		var keyOnly = key.Except(accepted, StringComparer.OrdinalIgnoreCase).ToList();
		var acceptedOnly = accepted.Except(key, StringComparer.OrdinalIgnoreCase).ToList();
		return keyOnly.Count > 0 || acceptedOnly.Count > 0 ? keyOnly : null;
	}

	private static string First(IReadOnlyList<string> values) =>
		values.Count > 0 ? values[0] : string.Empty;

	private static FdcDataset ToDataset(string? tier) =>
		tier is null || tier.Length == 0
			? FdcDataset.None
			: Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var parsed) ? parsed : FdcDataset.None;
}
