/// <summary>Runs the census (<c>census &lt;trace&gt;</c>) and pairs (<c>pairs &lt;census.tsv&gt; &lt;trace&gt;</c>) subcommands.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Classifies (or joins) and writes the requested output.</summary>
	/// <param name="tracePath">HoldoutGate trace JSONL.</param>
	/// <param name="censusTsvPath">P12.7 blocker-census TSV (pairs only; ignored for census).</param>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 success; 1 missing file, refused set, or failure.</returns>
	Task<int> RunAsync(string tracePath, string censusTsvPath, CancellationToken cancellationToken = default);
}
