{"content":"using System.Text.Json;
using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The auto-wrong census runner: reads a HoldoutGate trace, refuses anything but debug/batch
/// (D-029), classifies every auto-wrong line, writes the TSV, and prints the stderr summary.
/// The <c>pairs</c> subcommand joins P12.7 <c>window</c> blocker rows with route compound/other
/// against the trace.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusClassifier classifier,
	AutoWrongCensusOptions options,
	System.IO.TextWriter output,
	System.IO.TextWriter error) : IAutoWrongCensusRunner
{
	private const string TsvHeader =
		"holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	private static readonly string[] AllowedSets = ["debug", "batch"];

	/// <inheritdoc />
	public async Task<int> RunAsync(string tracePath, string censusTsvPath, CancellationToken cancellationToken = default)
	{
		if (!File.Exists(tracePath))
		{
			error.WriteLine($"AutoWrongCensus: trace file not found: {tracePath}");
			return 1;
		}

		var records = await ReadTraceAsync(tracePath, error, cancellationToken);
		if (records is null)
		{
			return 1;
		}

		foreach (var record in records)
		{
			if (!AllowedSets.Contains(record.Set))
			{
				error.WriteLine($"AutoWrongCensus: refusing trace: set '{record.Set}' (holdoutId {record.HoldoutId}, line {record.LineIndex}); allowed: debug, batch (D-029)");
				return 1;
			}
		}

		if (options.Command.Equals("pairs", StringComparison.OrdinalIgnoreCase))
		{
			return await RunPairsAsync(records, censusTsvPath, error, cancellationToken);
		}

		return await RunCensusAsync(records, error, cancellationToken);
	}

	private static async Task<List<TraceLine>?> ReadTraceAsync(string tracePath, System.IO.TextWriter error, CancellationToken cancellationToken)
	{
		var records = new List<TraceLine>();
		await using var stream = File.OpenRead(tracePath);
		using var reader = new StreamReader(stream);
		var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

		while (await reader.ReadLineAsync(cancellationToken) is { } line && line.Length > 0)
		{
			try
			{
				var record = JsonSerializer.Deserialize<TraceLine>(line, jsonOptions);
				if (record is not null)
				{
					records.Add(record);
				}
			}
			catch (Exception ex) when (ex is JsonException or NotSupportedException or InvalidOperationException)
			{
				error.WriteLine($"AutoWrongCensus: failed to parse trace line: {ex.Message}");
				return null;
			}
		}

		return records;
	}

	private async Task<int> RunCensusAsync(List<TraceLine> records, System.IO.TextWriter error, CancellationToken cancellationToken)
	{
		var classified = new List<(TraceLine Line, ClassificationResult Result)>();
		foreach (var record in records)
		{
			if (!record.Auto || record.Correct)
			{
				continue;
			}

			var result = classifier.Classify(record);
			if (result.Site.Length == 0)
			{
				error.WriteLine($"AutoWrongCensus: unknown atom path on {result.HoldoutId}#{result.LineIndex}; refusing to classify.");
				return 1;
			}

			classified.Add((record, result));
		}

		output.WriteLine(TsvHeader);
		foreach (var (record, result) in classified)
		{
			output.WriteLine(
				string.Join(
					'\t',
					record.HoldoutId,
					record.LineIndex.ToString(),
					record.Set,
					result.Relation,
					result.Site,
					result.OverrideKey,
					result.AcceptedTier,
					result.KeyTier,
					result.AcceptedState,
					result.KeyState,
					result.ParsedName,
					result.KeyHead,
					result.AcceptedDesc,
					result.KeyDesc,
					result.RawText));
		}

		WriteSummary(classified, error);
		return 0;
	}

	private async Task<int> RunPairsAsync(List<TraceLine> records, string censusTsvPath, System.IO.TextWriter error, CancellationToken cancellationToken)
	{
		if (!File.Exists(censusTsvPath))
		{
			error.WriteLine($"AutoWrongCensus: census file not found: {censusTsvPath}");
			return 1;
		}

		var traceByKey = new Dictionary<(string HoldoutId, int LineIndex), TraceLine>();
		foreach (var record in records)
		{
			traceByKey[(record.HoldoutId, record.LineIndex)] = record;
		}

		var pairs = new List<(TraceLine Line, ClassificationResult Result)>();
		foreach (var row in ReadCensusRows(censusTsvPath, error))
		{
			if (!row.Blocker.Equals("window", StringComparison.OrdinalIgnoreCase))
			{
				continue;
			}

			if (!row.Route.Equals("compound", StringComparison.OrdinalIgnoreCase) && !row.Route.Equals("other", StringComparison.OrdinalIgnoreCase))
			{
				continue;
			}

			if (!traceByKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				error.WriteLine($"AutoWrongCensus: pairs join miss: {row.HoldoutId}#{row.LineIndex}");
				continue;
			}

			pairs.Add((line, classifier.Classify(line)));
		}

		output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var (line, result) in pairs)
		{
			var parsedNameHead = string.Join(' ', SingularTokens(line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty));
			output.WriteLine(
				string.Join(
					'\t',
					line.HoldoutId,
					line.LineIndex.ToString(),
					parsedNameHead,
					result.KeyHead,
					line.RawText));
		}

		return 0;
	}

	private static IEnumerable<(string HoldoutId, int LineIndex, string Blocker, string Route)> ReadCensusRows(string censusTsvPath, System.IO.TextWriter error)
	{
		using var reader = new StreamReader(censusTsvPath);
		var header = reader.ReadLine()?.Split('\t') ?? [];
		var idx = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
		for (var i = 0; i < header.Length; i++)
		{
			idx[header[i].Trim()] = i;
		}

		foreach (var row in reader.ReadLines())
		{
			if (string.IsNullOrWhiteSpace(row))
			{
				continue;
			}

			var cells = row.Split('\t');
			if (!idx.TryGetValue("holdoutId", out var holdoutIdx)
				|| !int.TryParse(cells[holdoutIdx], out var lineIndex)
				|| !idx.TryGetValue("blocker", out var blockerIdx)
				|| !idx.TryGetValue("route", out var routeIdx))
			{
				error.WriteLine($"AutoWrongCensus: pairs: census row without required columns: {row}");
				continue;
			}

			yield return (cells[holdoutIdx], lineIndex, cells[blockerIdx], cells[routeIdx]);
		}
	}

	private void WriteSummary(List<(TraceLine Line, ClassificationResult Result)> classified, System.IO.TextWriter error)
	{
		var byRelation = classified.GroupBy(r => r.Result.Relation);
		error.WriteLine($"AutoWrongCensus: set={classified.FirstOrDefault().Result.Set} lines={classified.Count}");
		error.WriteLine("AutoWrongCensus: relation\tsite\tcount");
		foreach (var group in byRelation.OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			foreach (var cell in group.GroupBy(r => r.Result.Site).OrderBy(g => g.Key, StringComparer.Ordinal))
			{
				error.WriteLine($"{group.Key}\t{cell.Key}\t{cell.Count()}");
			}
		}

		var other = classified.Count(r => r.Result.Relation.Equals("other", StringComparison.OrdinalIgnoreCase));
		error.WriteLine($"AutoWrongCensus: other={other} ({classified.Count == 0 ? 0.0 : (double)other / classified.Count * 100:0.0}%)");

		var missing = classified.Where(r => r.Result.MissingField is not null).Select(r => $"{r.Result.HoldoutId}#{r.Result.LineIndex}:{r.Result.MissingField}");
		if (missing.Any())
		{
			error.WriteLine("AutoWrongCensus: missing fields: " + string.Join(' ', missing));
		}

		var overrideLines = classified.Where(r => r.Result.Site.Equals("override", StringComparison.OrdinalIgnoreCase)).ToList();
		error.WriteLine($"AutoWrongCensus: override-site lines={overrideLines.Count} overrideKey yes={overrideLines.Count(r => r.Result.OverrideKey.Equals("yes", StringComparison.OrdinalIgnoreCase))} no={overrideLines.Count(r => r.Result.OverrideKey.Equals("no", StringComparison.OrdinalIgnoreCase))}");

		var reuseLines = classified.Where(r => r.Result.Site.Equals("reuse", StringComparison.OrdinalIgnoreCase)).ToList();
		var shouldReuseFalse = reuseLines.Count(r => r.Line.Atoms.Count > 0 && r.Line.Atoms[0].LinkedIngredientId is not null
			&& !IngredientLineResolver.ShouldReuse(
				LetUsCook.Fdc.Parsing.IngredientLineParser.ComputeSlug(r.Line.Atoms[0].ParsedName),
				r.Line.Atoms[0].LinkedIngredientId));
		error.WriteLine($"AutoWrongCensus: reuse-site lines={reuseLines.Count} shouldReuseFalse={shouldReuseFalse}");

		var tierRows = classified.Where(r => r.Result.Relation.Equals("row-choice-tier", StringComparison.OrdinalIgnoreCase)).ToList();
		var keyHigher = tierRows.Count(r => TierRank(r.Result.KeyTier) > TierRank(r.Result.AcceptedTier));
		var acceptedHigher = tierRows.Count(r => TierRank(r.Result.AcceptedTier) > TierRank(r.Result.KeyTier));
		error.WriteLine($"AutoWrongCensus: row-choice-tier keyHigher={keyHigher} acceptedHigher={acceptedHigher}");
	}

	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};
}
