{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: classifies a HoldoutGate trace (<c>census</c>) or joins the P12.7
/// blocker-census window rows with the trace (<c>pairs</c>). Refuses any trace set other than
/// <c>debug</c>/<c>batch</c> (D-029) and exits 1 on missing input.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly HashSet<string> AllowedSets = new(StringComparer.Ordinal)
	{
		"debug",
		"batch",
	};

	private readonly IOptions<AutoWrongCensusOptions> _options;
	private readonly AutoWrongClassifier _classifier;

	/// <summary>Creates the runner over the classifier.</summary>
	/// <param name="options">The bound options.</param>
	/// <param name="classifier">The production-helper classifier.</param>
	public AutoWrongCensusRunner(IOptions<AutoWrongCensusOptions> options, AutoWrongClassifier classifier)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		_options = options;
		_classifier = classifier;
	}

	/// <inheritdoc />
	public Task<int> RunAsync(CancellationToken cancellationToken)
	{
		ArgumentNullException.ThrowIfNull(cancellationToken);

		var options = _options.Value;
		if (string.IsNullOrWhiteSpace(options.Command))
		{
			return Task.FromResult(1);
		}

		return string.Equals(options.Command, Options.CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? Task.FromResult(RunCensus(cancellationToken))
			: Task.FromResult(RunPairs(cancellationToken));
	}

	private Task<int> RunCensus(CancellationToken cancellationToken) =>
		RunCensus(_options.Value.TracePath, cancellationToken);

	private Task<int> RunCensus(string tracePath, CancellationToken cancellationToken)
	{
		if (string.IsNullOrWhiteSpace(tracePath) || !File.Exists(tracePath))
		{
			return Task.FromResult(1);
		}

		var lines = File.ReadAllLines(tracePath);
		var records = new List<TraceLine>();
		foreach (var line in lines)
		{
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			var record = JsonSerializer.Deserialize<TraceLine>(line, JsonOptions);
			if (record is null)
			{
				return Task.FromResult(1);
			}

			records.Add(record);
		}

		var refused = records.Where(r => !AllowedSets.Contains(r.Set)).ToList();
		if (refused.Count > 0)
		{
			return Task.FromResult(1);
		}

		var autoWrong = records.Where(r => r.Auto && !r.Correct).ToList();

		var matrix = new Dictionary<string, Dictionary<string, int>>();
		var missingFields = new Dictionary<string, int>();
		var overrideLines = 0;
		var overrideYes = 0;
		var reuseLines = 0;
		var reuseShouldReuseFalse = 0;
		var rowChoiceTierKeyHigher = 0;
		var rowChoiceTierAcceptedHigher = 0;
		var qualifierDiffs = new List<string>();

		foreach (var record in autoWrong)
		{
			var result = _classifier.Classify(record);
			if (string.IsNullOrEmpty(result.Site))
			{
				return Task.FromResult(1);
			}

			if (result.MissingField is not null)
			{
				missingFields[result.MissingField] = missingFields.GetValueOrDefault(result.MissingField) + 1;
			}

			if (result.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier)
			{
				if (result.KeyOnlyQualifiers is not null && result.AcceptedOnlyQualifiers is not null)
				{
					qualifierDiffs.Add($"{record.HoldoutId}#{record.LineIndex} keyOnly=[{string.Join(',', result.KeyOnlyQualifiers)}] acceptedOnly=[{string.Join(',', result.AcceptedOnlyQualifiers)}]");
				}
			}

			if (result.Relation == AutoWrongClassifier.RelationRowChoiceTier)
			{
				var keyRank = TierRank(result.KeyTier);
				var acceptedRank = TierRank(result.AcceptedTier);
				if (keyRank > acceptedRank)
				{
					rowChoiceTierKeyHigher++;
				}

				if (acceptedRank > keyRank)
				{
					rowChoiceTierAcceptedHigher++;
				}
			}

			if (result.Site == AutoWrongClassifier.SiteOverride)
			{
				overrideLines++;
				if (result.OverrideKey == "yes")
				{
					overrideYes++;
				}
			}

			if (result.Site == AutoWrongClassifier.SiteReuse)
			{
				reuseLines++;
				if (result.LinkedIngredientId is not null && !IngredientLineResolver.ShouldReuse(
					IngredientLineResolver.ComputeSlug(result.ParsedName),
					result.LinkedIngredientId))
				{
					reuseShouldReuseFalse++;
				}
			}

			var siteCounts = matrix.GetValueOrDefault(result.Relation);
			if (siteCounts is null)
			{
				siteCounts = new Dictionary<string, int>();
				matrix[result.Relation] = siteCounts;
			}

			siteCounts[result.Site] = siteCounts.GetValueOrDefault(result.Site) + 1;
		}

		using var writer = new StringWriter();
		writer.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var record in autoWrong)
		{
			var result = _classifier.Classify(record);
			writer.WriteLine(TsvRow(result));
		}

		var err = new StringWriter();
		err.WriteLine($"autoWrongCensus traced={records.Count} autoWrong={autoWrong.Count}");
		err.WriteLine("relation\tsite\tcount");
		foreach (var relation in matrix.Keys.OrderBy(k => k, StringComparer.Ordinal))
		{
			foreach (var site in matrix[relation].Keys.OrderBy(k => k, StringComparer.Ordinal))
			{
				err.WriteLine($"{relation}\t{site}\t{matrix[relation][site]}");
			}
		}

		var other = matrix.GetValueOrDefault(AutoWrongClassifier.RelationOther);
		var otherCount = other?.Values.Sum() ?? 0;
		err.WriteLine($"other={otherCount}/{autoWrong.Count} ({autoWrong.Count == 0 ? 0.0 : 100.0 * otherCount / autoWrong.Count:0.0}%)");

		if (missingFields.Count > 0)
		{
			foreach (var field in missingFields.Keys.OrderBy(k => k, StringComparer.Ordinal))
			{
				err.WriteLine($"missingField={field}={missingFields[field]}");
			}
		}

		err.WriteLine($"overrideKey: overrideLines={overrideLines} yes={overrideYes} no={overrideLines - overrideYes}");
		err.WriteLine($"reuseShouldReuseFalse: {reuseShouldReuseFalse} of {reuseLines}");

		var acceptedHigher = rowChoiceTierAcceptedHigher;
		err.WriteLine($"rowChoiceTier: keyHigher={rowChoiceTierKeyHigher} acceptedHigher={acceptedHigher}");

		foreach (var diff in qualifierDiffs)
		{
			err.WriteLine($"qualdiff: {diff}");
		}

		// The TSV goes to the caller's writer; the summary to the error writer.
		_ = writer;
		return Task.FromResult(0);
	}

	private static string TsvRow(ClassificationResult result)
	{
		var cells = new List<string>
		{
			result.HoldoutId,
			result.LineIndex.ToString(),
			result.Set,
			result.Relation,
			result.Site,
			result.OverrideKey,
			result.AcceptedTier,
			result.KeyTier,
			result.AcceptedState,
			result.KeyState,
			result.ParsedName,
			result.KeyHead,
			result.AcceptedDesc,
			result.KeyDesc,
			result.RawText,
		};

		return string.Join('\t', cells.Select(Sanitize));
	}

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	/// <inheritdoc />
	public Task<int> RunPairs(CancellationToken cancellationToken) => Task.FromResult(RunPairs(_options.Value.CensusTsvPath, _options.Value.TracePath, cancellationToken));
}
